// frontend/src/pages/TransactionLog.jsx

import React, { useEffect, useState } from "react";
import { fetchTrades, fetchRiskLogs } from "../services/api";

export default function TransactionLog() {
  const [trades,   setTrades]   = useState([]);
  const [riskMap,  setRiskMap]  = useState({});
  const [page,     setPage]     = useState(1);
  const [filter,   setFilter]   = useState("ALL"); // ALL | HIGH | MEDIUM | LOW

  useEffect(() => {
    fetchTrades(page).then(setTrades);
  }, [page]);

  useEffect(() => {
    fetchRiskLogs().then((logs) => {
      const map = {};
      logs.forEach((l) => { map[l.trade_id] = l; });
      setRiskMap(map);
    });
  }, []);

  const getRiskLabel = (tradeId) => {
    const log = riskMap[tradeId];
    if (!log) return { label: "CLEAN", color: "#22c55e", score: 0 };
    if (log.risk_score >= 60) return { label: "HIGH",   color: "#ef4444", score: log.risk_score };
    if (log.risk_score >= 30) return { label: "MEDIUM", color: "#f97316", score: log.risk_score };
    return                           { label: "LOW",    color: "#facc15", score: log.risk_score };
  };

  const filtered = trades.filter((t) => {
    if (filter === "ALL") return true;
    return getRiskLabel(t.trade_id).label === filter;
  });

  return (
    <div style={{ padding: "24px", background: "#0f172a", minHeight: "100vh", color: "#f1f5f9" }}>
      <h1>📋 Transaction Risk Analysis</h1>

      {/* Filter buttons */}
      <div style={{ display: "flex", gap: "8px", marginBottom: "20px" }}>
        {["ALL", "HIGH", "MEDIUM", "LOW", "CLEAN"].map((f) => (
          <button key={f} onClick={() => setFilter(f)} style={{
            padding: "6px 16px", borderRadius: "6px", border: "none", cursor: "pointer",
            background: filter === f ? "#3b82f6" : "#1e293b", color: "#f1f5f9"
          }}>
            {f}
          </button>
        ))}
      </div>

      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.9rem" }}>
        <thead>
          <tr style={{ borderBottom: "2px solid #334155", color: "#94a3b8" }}>
            <th style={{ textAlign: "left", padding: "10px" }}>Trade ID</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Seller</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Buyer</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Stock</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Price</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Qty</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Time</th>
            <th style={{ textAlign: "left", padding: "10px" }}>Risk</th>
          </tr>
        </thead>
        <tbody>
          {filtered.map((t) => {
            const risk = getRiskLabel(t.trade_id);
            return (
              <tr key={t.trade_id} style={{
                borderBottom: "1px solid #1e293b",
                background: risk.label === "HIGH" ? "rgba(239,68,68,0.05)" : "transparent"
              }}>
                <td style={{ padding: "10px" }}>#{t.trade_id}</td>
                <td style={{ padding: "10px" }}>{t.seller_name || t.seller_id}</td>
                <td style={{ padding: "10px" }}>{t.buyer_name  || t.buyer_id}</td>
                <td style={{ padding: "10px" }}>{t.symbol      || t.stock_id}</td>
                <td style={{ padding: "10px" }}>${t.price}</td>
                <td style={{ padding: "10px" }}>{t.quantity}</td>
                <td style={{ padding: "10px" }}>{new Date(t.timestamp).toLocaleString()}</td>
                <td style={{ padding: "10px" }}>
                  <span style={{
                    background: risk.color, color: "#000",
                    padding: "2px 8px", borderRadius: "4px",
                    fontSize: "0.75rem", fontWeight: "bold"
                  }}>
                    {risk.label} {risk.score > 0 ? `(${risk.score})` : ""}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      {/* Pagination */}
      <div style={{ display: "flex", gap: "12px", marginTop: "20px", alignItems: "center" }}>
        <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={page === 1}
          style={{ padding: "8px 16px", background: "#1e293b", color: "#f1f5f9", border: "none", borderRadius: "6px", cursor: "pointer" }}>
          ← Prev
        </button>
        <span style={{ color: "#94a3b8" }}>Page {page}</span>
        <button onClick={() => setPage((p) => p + 1)}
          style={{ padding: "8px 16px", background: "#1e293b", color: "#f1f5f9", border: "none", borderRadius: "6px", cursor: "pointer" }}>
          Next →
        </button>
      </div>
    </div>
  );
}
